// Worker entry point (see wrangler.jsonc). It reuses the fetch handler that
// OpenNext generates and adds the cron trigger that clears emails 30 days
// after each event: https://opennext.js.org/cloudflare/howtos/custom-worker
// Not type-checked (excluded in tsconfig.json): Wrangler bundles it.
// @ts-ignore `.open-next/worker.js` is generated by `yarn cf:build`
import { default as handler } from "./.open-next/worker.js";

type Env = { NEXTAUTH_URL: string; NEXTAUTH_SECRET: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void };
type OpenNextHandler = {
  fetch(request: Request, env: Env, ctx: Ctx): Promise<Response>;
};

const app = handler as OpenNextHandler;

export default {
  fetch: app.fetch,
  // Runs the scrub through the app's own route, which owns the database
  // client, instead of bundling a second Prisma client into the Worker.
  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    const response = await app.fetch(
      new Request(new URL("/api/cron/scrub-emails", env.NEXTAUTH_URL), {
        method: "POST",
        headers: { authorization: `Bearer ${env.NEXTAUTH_SECRET}` },
      }),
      env,
      ctx,
    );
    if (!response.ok) {
      throw new Error(`Email scrub failed with status ${response.status}`);
    }
  },
};
